    TransformEvaluator<Object> evaluator = new TransformEvaluator<Object>() {

        @Override
        public void processElement(WindowedValue<Object> element) throws Exception {
        }

        @Override
        public TransformResult<Object> finishBundle() throws Exception {
            return result;
        }
    };
    WindowedValue<String> fooBytes = WindowedValue.valueInGlobalWindow("foo");
    CommittedBundle<String> inputBundle = bundleFactory.createBundle(created).add(fooBytes).commit(Instant.now());
    when(registry.forApplication(downstreamProducer, inputBundle)).thenReturn(evaluator);
    DirectTransformExecutor<String> executor = new DirectTransformExecutor<>(evaluationContext, registry, Collections.<ModelEnforcementFactory>singleton(new ThrowingEnforcementFactory(ThrowingEnforcementFactory.When.AFTER_ELEMENT)), inputBundle, downstreamProducer, completionCallback, transformEvaluationState);
    Future<?> task = Executors.newSingleThreadExecutor().submit(executor);
    thrown.expectCause(isA(RuntimeException.class));
    thrown.expectMessage("afterElement");
    task.get();
}

