    ImmutableList.<PCollectionView<?>>of(singletonView), mainOutputTag, additionalOutputTags, ImmutableMap.<TupleTag<?>, PCollection<?>>of(mainOutputTag, output), ParDoEvaluator.<Integer, Integer>defaultRunnerFactory());
}

