@Category(NeedsRunner.class)
public void readPipeline() throws Exception {
    Timestamp timestamp = Timestamp.ofTimeMicroseconds(12345);
    SpannerConfig spannerConfig = SpannerConfig.create().withProjectId("test").withInstanceId("123").withDatabaseId("aaa").withServiceFactory(serviceFactory);
    PCollectionView<Transaction> tx = pipeline.apply("tx", SpannerIO.createTransaction().withSpannerConfig(spannerConfig));
    PCollection<Struct> one = pipeline.apply("read q", SpannerIO.read().withSpannerConfig(spannerConfig).withQuery("SELECT * FROM users").withTransaction(tx));
    PCollection<Struct> two = pipeline.apply("read r", SpannerIO.read().withSpannerConfig(spannerConfig).withTimestamp(Timestamp.now()).withTable("users").withColumns("id", "name").withTransaction(tx));
    when(serviceFactory.mockDatabaseClient().readOnlyTransaction(any(TimestampBound.class))).thenReturn(mockTx);
    when(mockTx.executeQuery(Statement.of("SELECT 1"))).thenReturn(ResultSets.forRows(Type.struct(), Collections.<Struct>emptyList()));
    when(mockTx.executeQuery(Statement.of("SELECT * FROM users"))).thenReturn(ResultSets.forRows(FAKE_TYPE, FAKE_ROWS));
    when(mockTx.read("users", KeySet.all(), Arrays.asList("id", "name"))).thenReturn(ResultSets.forRows(FAKE_TYPE, FAKE_ROWS));
    when(mockTx.getReadTimestamp()).thenReturn(timestamp);
    PAssert.that(one).containsInAnyOrder(FAKE_ROWS);
    PAssert.that(two).containsInAnyOrder(FAKE_ROWS);
    pipeline.run();
    verify(serviceFactory.mockDatabaseClient(), times(2)).readOnlyTransaction(TimestampBound.ofReadTimestamp(timestamp));
}

